const v = await fetch('https://www.tamuso.com/voice/oda-295mgy');
const t = await v.text();
const title = (t.match(/<title>([^<]+)/) || [])[1];
const h1 = (t.match(/<h1[\s\S]*?<\/h1>/) || [])[0];
console.log(title);
console.log(h1);
const tr = await fetch('https://www.tamuso.com/country/tr');
const th = await tr.text();
console.log('tr hreflang', (th.match(/hreflang/g) || []).length);
console.log('tr canonical', (th.match(/rel="canonical" href="([^"]+)/) || [])[1]);
